package au.edu.uow.csci318.assessment.domain;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class AssessmentTest{@Test void rejectsBadWeight(){assertThrows(IllegalArgumentException.class,()->new Assessment(UUID.randomUUID(),"A","Essay",101d,null,null,null,60,null));}@Test void completionIsNotRepeatable(){var a=new Assessment(UUID.randomUUID(),"A","Essay",20d,null,null,null,60,null);a.markCompleted();assertThrows(IllegalStateException.class,a::markCompleted);}@Test void rejectsNegativeWorkload(){var a=new Assessment(UUID.randomUUID(),"A","Essay",20d,null,null,null,60,null);assertThrows(IllegalArgumentException.class,()->a.changeEstimatedWorkload(-1));}@Test void acceptsAnnualTeachingWeek(){var a=new Assessment(UUID.randomUUID(),"Innovation Fair","Presentation",5d,null,26,null,60,null);assertEquals(26,a.getDueWeek());assertThrows(IllegalArgumentException.class,()->a.changeDeadline(null,53));}}
